    """Directory holding the project's compose files."""
    if name:
        base = ctx.runtime.get("projects_path") or os.path.join(root_dir(os.environ), "sites")
        return os.path.join(os.path.expanduser(str(base)), name), False
    if ctx.runtime.get("path"):
        return os.path.join(ctx.cwd, os.path.expanduser(str(ctx.runtime["path"]))), False
    return ctx.cwd, True


