        if path:
            base_dirs.append(os.path.dirname(os.path.abspath(path)))
    files = container.compose_files(directory, ctx.runtime.get("custom-compose"), ctx.output,
                                    base_dirs=base_dirs, search_parents=search_parents)
    if not files:
        raise AppctlError(f"No compose file found in '{os.path.abspath(directory)}'.")
    merged = container.load_compose_config(files)
    if assoc.get("services"):
        for service in container.compose_services(merged):
            ctx.output.line(service)
        return
    ctx.output.stdout.write(yaml.safe_dump(merged, sort_keys=False, default_flow_style=False))


